WITH flattened_attrs AS (SELECT id, host, level, latency_ms, payload_json, SIZE(context) AS num_context, COALESCE(context['trace'], 'none') AS trace_or_default FROM app_logs WHERE host IN ('h2', 'h1', 'h4')) SELECT CASE WHEN latency_ms >= 2439 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, level, COUNT(*) FILTER (WHERE level = 'WARN') AS warn_rows, SIZE(COLLECT_SET(level)) AS num_levels, PERCENTILE_APPROX(num_context, 0.9) AS num_context_p90, MAX(num_context) FILTER (WHERE level = 'DEBUG') AS debug_max_num_context, SUM(CASE WHEN level = 'INFO' THEN latency_ms ELSE 0 END) AS info_latency_ms FROM flattened_attrs GROUP BY CASE WHEN latency_ms >= 2439 THEN 'PREMIUM' ELSE 'STANDARD' END, level;
